// LESS format — define @variables here as needed
// Generated by sumd for codot

app {
  name: codot;
  version: 0.1.0;
}

interface[type="web"] {
  framework: node;
}

workflow[name="install"] {
  trigger: manual;
  step-1: run cmd=npm install;
}

workflow[name="dev"] {
  trigger: manual;
  step-1: run cmd=npm run serve;
}

workflow[name="build"] {
  trigger: manual;
  step-1: run cmd=npm run build;
}

workflow[name="test"] {
  trigger: manual;
  step-1: run cmd=npm test;
}

workflow[name="lint"] {
  trigger: manual;
  step-1: run cmd=npm run lint;
}

workflow[name="fmt"] {
  trigger: manual;
  step-1: run cmd=npm run format;
}

workflow[name="clean"] {
  trigger: manual;
  step-1: run cmd=rm -rf node_modules dist build .cache;
}

workflow[name="help"] {
  trigger: manual;
  step-1: run cmd=task --list;
}

deploy {
  target: npm;
}

environment[name="local"] {
  runtime: node;
}
```
